def _theforge_verbs() -> set[str]:
    out = subprocess.run(
        [PY, "-m", "theforge", "--help"],
        cwd=REPO,
        capture_output=True,
        text=True,
    )
    if out.returncode != 0:
        return set()
    m = re.search(r"\{([^}]+)\}", out.stdout)
    return set(m.group(1).split(",")) if m else set()
